mapper.select:
SELECT co.iso2 AS code,
COALESCE(t.translation, co.name, co.native) COALESCE(co.name, co.native) AS name, COALESCE(co.native, co.name) AS nameLocal, co.phonecode AS phoneCode, co.currency AS currency, co.postal_code_format AS postalCodeFormat, co.postal_code_regex AS postalCodeRegex FROM countries co
LEFT JOIN translations t ON t.place_type = 'country' AND t.place_id = co.id AND t.language = #{language}
WHERE co.iso2 IN #{code}

SELECT s.id AS id, COALESCE(NULLIF(s.iso3166_2, ''), CONCAT('S', s.id)) AS code,
COALESCE(t.translation, s.name, s.native) COALESCE(s.name, s.native) AS name, COALESCE(s.native, s.name) AS nameLocal, s.type AS type FROM states s
LEFT JOIN translations t ON t.place_type = 'state' AND t.place_id = s.id AND t.language = #{language}
WHERE s.country_code = #{country}
AND s.type <> 'geographical unit' AND NOT ( s.country_code = 'PH' AND s.type = 'region' AND EXISTS (SELECT 1 FROM states ch WHERE ch.parent_id = s.id) ) ORDER BY s.name

SELECT s.id                                                             AS id,
       COALESCE(NULLIF(s.iso3166_2, ''), CONCAT('S', s.id))             AS code,

    COALESCE(t.translation, s.name, s.native)
    COALESCE(s.name, s.native)
                                                               AS name,
       COALESCE(s.native, s.name)                                       AS nameLocal,
       s.type                                                           AS type
FROM states s

    LEFT JOIN translations t
           ON t.place_type = 'state' AND t.place_id = s.id AND t.language = #{language}

WHERE


        (s.iso3166_2 IN
        #{code}
        OR s.id IN
        #{sid}
        )


        s.iso3166_2 IN
        #{code}


        s.id IN
        #{sid}

SELECT c.id                             AS id,
       COALESCE(c.name, c.native)       AS name,
       COALESCE(c.native, c.name)       AS nameLocal,
       c.population                     AS population
FROM cities c
WHERE c.country_code = #{country}



    AND c.state_id = #{stateId}


    AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.native LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY c.population DESC, c.name
LIMIT #{limit}

SELECT c.id                             AS id,
       COALESCE(c.name, c.native)       AS name,
       COALESCE(c.native, c.name)       AS nameLocal,
       c.population                     AS population
FROM translations t
         INNER JOIN cities c ON c.id = t.place_id
WHERE t.place_type = 'city'
  AND t.language = #{language}
  AND t.translation LIKE CONCAT(#{keywordPrefix}, '%')
  AND c.country_code = #{country}



    AND c.state_id = #{stateId}

ORDER BY c.population DESC
LIMIT #{limit}

SELECT c.id AS id,
COALESCE(t.translation, c.name, c.native) COALESCE(c.name, c.native) AS name, COALESCE(c.native, c.name) AS nameLocal, c.population AS population FROM cities c
LEFT JOIN translations t ON t.place_type = 'city' AND t.place_id = c.id AND t.language = #{language}
WHERE c.id IN #{cid}

SELECT c.id                             AS id,
       COALESCE(c.name, c.native)       AS name,
       COALESCE(c.native, c.name)       AS nameLocal,
       c.population                     AS population
FROM cities c
WHERE c.id = #{id}
  AND c.country_code = #{country}



    AND c.state_id = #{stateId}
